insert into public.country_occupation_profiles (
  profile_key,country_code,canonical_career_id,official_title,official_code_system,official_code_version,
  official_unit_group_code,currency,registration_required,registration_authority,registration_url,
  publication_status,source_checked_at,updated_at
) values
  ('IE:accountant','IE','accountant','Chartered and certified accountants — accountant scope','SOC','SOC 2010','2421','EUR',false,null,null,'profile_ready','2026-08-11',now()),
  ('IE:financial-analyst','IE','financial-analyst','Finance and investment analysts and advisers','SOC','SOC 2010','3534','EUR',false,null,null,'profile_ready','2026-08-11',now()),
  ('IE:business-analyst','IE','business-analyst','Management consultants and business analysts','SOC','SOC 2010','2423','EUR',false,null,null,'profile_ready','2026-08-11',now()),
  ('IE:supply-chain-analyst','IE','supply-chain-analyst','Buyers and procurement officers — supply-chain / procurement analysis scope','SOC','SOC 2010','3541','EUR',false,null,null,'profile_ready','2026-08-11',now()),
  ('IE:human-resources-specialist','IE','human-resources-specialist','Human resources and industrial relations officers','SOC','SOC 2010','3562','EUR',false,null,null,'profile_ready','2026-08-11',now()),
